import { ArrowDownRight, ArrowUpRight, Clock } from "lucide-react";
import { formatNumber, formatTimestamp } from "../utils/format";

/**
 * ResultCard Component
 *
 * Displays the conversion result with exchange rate, trend indicator, and timestamp.
 *
 * Features:
 * - Shows converted amount and exchange rate
 * - Visual trend indicator (up/down arrows with percentage)
 * - Last update timestamp
 * - Responsive glass-morphism design
 * - Accessible markup with semantic HTML
 *
 * @component
 * @param {Object} props - Component props
 * @param {Object} props.result - Conversion result data
 * @param {number} props.result.amount - Original amount
 * @param {string} props.result.fromCurrency - Source currency code
 * @param {string} props.result.toCurrency - Target currency code
 * @param {number} props.result.rate - Exchange rate
 * @param {number} props.result.converted - Converted amount
 * @param {number} props.trend - Trend percentage (+/- value)
 * @param {string} props.lastUpdated - ISO timestamp of update
 * @returns {React.ReactElement} Result card with conversion details
 *
 * @example
 * <ResultCard
 *   result={{ amount: 100, fromCurrency: "USD", toCurrency: "INR", rate: 83.12, converted: 8312 }}
 *   trend={-1.5}
 *   lastUpdated={new Date().toISOString()}
 * />
 */
export default function ResultCard({ result, trend, lastUpdated }) {
  const isUp = trend >= 0;

  return (
    <div className="mt-5 rounded-2xl border border-white/40 bg-white/60 p-4 shadow-glass backdrop-blur-xl dark:border-white/10 dark:bg-slate-900/50">
      <p className="text-xs uppercase tracking-[0.2em] text-slate-500 dark:text-slate-400">
        Conversion Result
      </p>

      <p className="mt-2 text-2xl font-bold">
        {formatNumber(result.converted)} <span className="text-lg">{result.toCurrency}</span>
      </p>

      <p className="mt-1 text-sm text-slate-600 dark:text-slate-300">
        {formatNumber(result.amount, 2)} {result.fromCurrency} ={" "}
        {formatNumber(result.converted)} {result.toCurrency}
      </p>

      <p className="mt-1 text-xs text-slate-500 dark:text-slate-400">
        Exchange rate: 1 {result.fromCurrency} = {formatNumber(result.rate, 6)} {result.toCurrency}
      </p>

      {/* Trend and Timestamp */}
      <div className="mt-3 flex items-center justify-between gap-3 text-sm">
        {/* Trend Indicator */}
        <span
          className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-sm font-medium ${
            isUp
              ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300"
              : "bg-rose-100 text-rose-700 dark:bg-rose-900/40 dark:text-rose-300"
          }`}
          aria-label={`Trend: ${isUp ? "up" : "down"} ${trend.toFixed(2)}%`}
        >
          {isUp ? <ArrowUpRight size={14} aria-hidden="true" /> : <ArrowDownRight size={14} aria-hidden="true" />}
          <span>{isUp ? "+" : ""}{trend.toFixed(2)}%</span>
        </span>

        {/* Last Updated Timestamp */}
        <span className="inline-flex items-center gap-1 text-xs text-slate-500 dark:text-slate-400">
          <Clock size={12} aria-hidden="true" />
          <time dateTime={lastUpdated}>{formatTimestamp(lastUpdated)}</time>
        </span>
      </div>
    </div>
  );
}

import React from "react";

/**
 * Simple SVG sparkline component.
 * data: array of numbers
 */
export default function Sparkline({ data = [], width = 120, height = 32, stroke = "#7dd3fc" }) {
  if (!data || data.length === 0) {
    return <svg width={width} height={height} aria-hidden="true" />;
  }

  const max = Math.max(...data);
  const min = Math.min(...data);
  const len = data.length;
  const stepX = width / Math.max(1, len - 1);

  const points = data
    .map((d, i) => {
      const x = i * stepX;
      const t = max === min ? 0.5 : (d - min) / (max - min);
      const y = height - t * height;
      return `${x},${y}`;
    })
    .join(" ");

  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none" role="img" aria-label="trend sparkline">
      <polyline
        fill="none"
        stroke={stroke}
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        points={points}
        style={{ filter: "drop-shadow(0 2px 6px rgba(0,0,0,0.25))" }}
      />
    </svg>
  );
}

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  body {
    @apply min-h-screen bg-slate-100 text-slate-900 antialiased transition-colors duration-300 dark:bg-slate-950 dark:text-slate-100;
  }
}

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  body {
    @apply min-h-screen overflow-x-hidden bg-slate-100 text-slate-900 antialiased transition-colors duration-300 dark:bg-slate-950 dark:text-slate-100;
  }
}

@layer utilities {
  .background-scene {
    perspective: 1200px;
    transform-style: preserve-3d;
  }

  .scene-light {
    @apply absolute inset-x-1/2 top-20 h-[28rem] w-[28rem] -translate-x-1/2 rounded-full;
    background: radial-gradient(circle, rgba(255, 255, 255, 0.18) 0%, rgba(255, 255, 255, 0.08) 18%, rgba(255, 255, 255, 0) 65%);
    filter: blur(34px);
    opacity: 0.5;
    animation: halo-spin 42s linear infinite;
  }

  .floating-sphere {
    @apply absolute rounded-full bg-white/0;
    transform-style: preserve-3d;
    /* Glass / crystal look: translucent core, crisp rim, inner shadow and subtle refraction */
    background:
      radial-gradient(circle at 28% 26%, rgba(255,255,255,0.98) 0 3%, rgba(255,255,255,0.45) 9%, rgba(255,255,255,0.06) 16%, transparent 26%),
      radial-gradient(circle at 72% 74%, rgba(6, 10, 20, 0.32), rgba(6, 10, 20, 0) 46%),
      radial-gradient(circle at 50% 52%, rgba(255,255,255,0.06), rgba(255,255,255,0.02));
    border: 1px solid rgba(255,255,255,0.08);
    backdrop-filter: blur(6px) saturate(1.06);
    -webkit-backdrop-filter: blur(6px) saturate(1.06);
    box-shadow:
      inset 18px 24px 48px rgba(255,255,255,0.06),
      inset -18px -24px 48px rgba(2,6,23,0.22),
      0 20px 48px rgba(2,6,23,0.28);
    filter: contrast(1.02) saturate(1.06);
    mix-blend-mode: screen;
    animation:
      sphere-float 18s ease-in-out infinite alternate,
      sphere-rotate 14s ease-in-out infinite alternate,
      sphere-pulse 10s ease-in-out infinite;
  }

  .floating-sphere::before {
    content: "";
    @apply absolute rounded-full;
    inset: 10%;
    /* crisp specular highlight */
    background: linear-gradient(135deg, rgba(255,255,255,0.94) 0%, rgba(255,255,255,0.5) 12%, rgba(255,255,255,0.18) 26%, rgba(255,255,255,0) 46%);
    transform: translateZ(20px) scale(0.98);
    filter: blur(2px) contrast(1.02);
    opacity: 0.95;
  }

  .floating-sphere::after {
    content: "";
    @apply absolute rounded-full;
    inset: -6%;
    /* subtle frosted rim / ground shadow to sell depth */
    background: radial-gradient(circle at 68% 72%, rgba(2,6,23,0.42), rgba(2,6,23,0) 54%);
    filter: blur(24px) contrast(0.95);
    transform: translate3d(0, 8%, -120px) scale(0.9);
    opacity: 0.6;
  }

  .sphere-one {
    top: -4rem;
    left: -4rem;
    height: clamp(14rem, 24vw, 24rem);
    width: clamp(14rem, 24vw, 24rem);
    animation-duration: 20s, 13s, 11s;
  }

  .sphere-two {
    top: 7rem;
    right: -6rem;
    height: clamp(12rem, 21vw, 21rem);
    width: clamp(12rem, 21vw, 21rem);
    background:
      radial-gradient(circle at 30% 28%, rgba(255, 255, 255, 0.92) 0 4%, rgba(255, 255, 255, 0.42) 9%, rgba(255, 255, 255, 0.08) 18%, transparent 28%),
      radial-gradient(circle at 70% 72%, rgba(2, 6, 23, 0.3), rgba(2, 6, 23, 0) 44%),
      radial-gradient(circle at 40% 38%, rgba(168, 85, 247, 0.48), rgba(59, 130, 246, 0.18) 58%, rgba(15, 23, 42, 0.35) 100%);
    animation-duration: 24s, 15s, 12s;
    animation-direction: alternate-reverse, alternate, alternate;
  }

  .sphere-three {
    bottom: -7rem;
    left: 50%;
    height: clamp(13rem, 23vw, 23rem);
    width: clamp(13rem, 23vw, 23rem);
    background:
      radial-gradient(circle at 31% 27%, rgba(255, 255, 255, 0.94) 0 4%, rgba(255, 255, 255, 0.4) 10%, rgba(255, 255, 255, 0.06) 18%, transparent 28%),
      radial-gradient(circle at 68% 72%, rgba(2, 6, 23, 0.34), rgba(2, 6, 23, 0) 44%),
      radial-gradient(circle at 44% 36%, rgba(14, 165, 233, 0.44), rgba(34, 211, 238, 0.2) 58%, rgba(15, 23, 42, 0.36) 100%);
    translate: -50% 0;
    animation-duration: 26s, 17s, 13s;
  }

  .sphere-four {
    top: 48%;
    left: 18%;
    height: clamp(7rem, 12vw, 12rem);
    width: clamp(7rem, 12vw, 12rem);
    background:
      radial-gradient(circle at 28% 24%, rgba(255, 255, 255, 0.96) 0 6%, rgba(255, 255, 255, 0.28) 14%, transparent 28%),
      radial-gradient(circle at 70% 72%, rgba(2, 6, 23, 0.26), rgba(2, 6, 23, 0) 48%),
      radial-gradient(circle at 40% 38%, rgba(251, 191, 36, 0.34), rgba(244, 114, 182, 0.14) 58%, rgba(15, 23, 42, 0.28) 100%);
    animation-duration: 19s, 10s, 9s;
    animation-direction: alternate, alternate-reverse, alternate;
  }

  .ambient-grid {
    @apply absolute inset-0 opacity-[0.04] dark:opacity-[0.06];
    background-image:
      linear-gradient(rgba(148, 163, 184, 0.35) 1px, transparent 1px),
      linear-gradient(90deg, rgba(148, 163, 184, 0.35) 1px, transparent 1px);
    background-size: 72px 72px;
    transform: translateZ(-160px) scale(1.2);
    animation: grid-drift 48s linear infinite;
    mask-image: radial-gradient(circle at center, black 45%, transparent 100%);
  }
}

@keyframes ambient-float {
  0% {
    transform: translate3d(0, 0, 0) scale(1);
  }
  50% {
    transform: translate3d(1.5rem, -1rem, 0) scale(1.06);
  }
  100% {
    transform: translate3d(-1rem, 1.25rem, 0) scale(0.98);
  }
}

@keyframes ambient-pulse {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 0.85;
  }
}

@keyframes sphere-float {
  0% {
    transform: translate3d(0, 0, 0) rotateX(8deg) rotateY(-10deg) rotateZ(0deg) scale(1);
  }
  50% {
    transform: translate3d(1rem, -1.25rem, 60px) rotateX(-10deg) rotateY(12deg) rotateZ(8deg) scale(1.05);
  }
  100% {
    transform: translate3d(-1rem, 1rem, -30px) rotateX(10deg) rotateY(-6deg) rotateZ(-6deg) scale(0.98);
  }
}

@keyframes sphere-rotate {
  0% {
    filter: saturate(1.08) contrast(1.02) hue-rotate(0deg);
  }
  100% {
    filter: saturate(1.18) contrast(1.08) hue-rotate(10deg);
  }
}

@keyframes sphere-pulse {
  0%,
  100% {
    opacity: 0.76;
  }
  50% {
    opacity: 0.96;
  }
}

@keyframes ambient-tilt {
  0% {
    transform: rotateX(10deg) rotateY(-8deg) translate3d(0, 0, 0) scale(1);
  }
  100% {
    transform: rotateX(-10deg) rotateY(8deg) translate3d(0.75rem, -0.75rem, 0) scale(1.04);
  }
}

@keyframes halo-spin {
  from {
    transform: translateX(-50%) rotate(0deg) scale(1);
  }
  to {
    transform: translateX(-50%) rotate(360deg) scale(1.08);
  }
}

@keyframes grid-drift {
  from {
    background-position: 0 0;
  }
  to {
    background-position: 72px 72px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .floating-sphere,
  .ambient-grid,
  .scene-light {
    animation: none !important;
  }
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

/**
 * Vite Configuration for Currency Converter
 * 
 * Features:
 * - React Fast Refresh for development
 * - Production optimizations:
 *   - CSS minification
 *   - JS minification and tree-shaking
 *   - Asset optimization
 *   - Source maps for debugging
 * - Environment variable support
 * 
 * @see https://vitejs.dev/config/
 */

export default defineConfig({
  plugins: [react()],
  build: {
    // Optimize build output
    minify: "terser",
    terserOptions: {
      compress: {
        drop_console: false, // Keep console logs for debugging (set to true for production)
        dead_code: true,
      },
    },
    rollupOptions: {
      output: {
        // Manual chunk splitting for better caching
        manualChunks: {
          vendor: ["react", "react-dom"],
          ui: ["lucide-react", "sonner"],
        },
      },
    },
    // Increase chunk size warning threshold (default is 500kb)
    chunkSizeWarningLimit: 1000,
    // Enable source maps for production debugging
    sourcemap: false, // Set to true for production debugging
  },

  // Optimization settings
  optimizeDeps: {
    include: ["react", "react-dom", "lucide-react", "sonner"],
  },
});

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

/**
 * Vite Configuration for Currency Converter
 * 
 * Features:
 * - React Fast Refresh for development
 * - Production optimizations:
 *   - CSS minification
 *   - JS minification and tree-shaking
 *   - Asset optimization
 *   - Source maps for debugging
 * - Environment variable support
 * 
 * @see https://vitejs.dev/config/
 */

export default defineConfig({
  plugins: [react()],
  build: {
    // Use esbuild for minification (faster, no additional dependencies)
    minify: "esbuild",
    rollupOptions: {
      output: {
        // Manual chunk splitting for better caching
        manualChunks: {
          vendor: ["react", "react-dom"],
          ui: ["lucide-react", "sonner"],
        },
      },
    },
    // Increase chunk size warning threshold (default is 500kb)
    chunkSizeWarningLimit: 1000,
    // Enable source maps for production debugging
    sourcemap: false, // Set to true for production debugging
  },

  // Optimization settings
  optimizeDeps: {
    include: ["react", "react-dom", "lucide-react", "sonner"],
  },
});
